function c(t){const i=Number(t);return isFinite(i)?Math.round(i).toLocaleString("zh-CN"):"0"}function a(t,{prefix:i="￥"}={}){const e=Number(t)||0;return i+e.toLocaleString("zh-CN",{minimumFractionDigits:0,maximumFractionDigits:2})}function m(t,i={}){const{forceSuffix:e=!1,unit:u=""}=i,s=Number(t);if(!isFinite(s))return"0";const r=s<0?"-":"",n=Math.abs(s);if(n<1e4){const o=c(n);return r+o+u}if(n<1e8){const o=(n/1e4).toFixed(1);return r+o+"万"}if(n<1e12){const o=(n/1e8).toFixed(2);return r+o+"亿"}const f=(n/1e12).toFixed(2);return r+f+"万亿"}function b(t){return c(t)+" 积分"}export{b as a,c as b,a as c,m as f};
